-- Classroom gradebook is deliberately separate from governed formal results.
create table public.classroom_grade_items(id uuid primary key default gen_random_uuid(),school_id uuid not null references public.schools(id) on delete cascade,classroom_id uuid not null,title text not null,kind text not null check(kind in('assignment','quiz','participation','other')),source_id uuid,maximum_score numeric(7,2) not null check(maximum_score>0),weight numeric(6,3) not null default 1 check(weight>=0),status text not null default 'draft' check(status in('draft','released','archived')),created_by uuid not null references auth.users(id),created_at timestamptz not null default now(),unique(school_id,id),foreign key(school_id,classroom_id) references public.learning_classrooms(school_id,id) on delete cascade);
create table public.classroom_grades(id uuid primary key default gen_random_uuid(),school_id uuid not null references public.schools(id) on delete cascade,grade_item_id uuid not null,student_id uuid not null,score numeric(7,2) not null check(score>=0),feedback text,released_at timestamptz,graded_by uuid not null references auth.users(id),graded_at timestamptz not null default now(),unique(grade_item_id,student_id),unique(school_id,id),foreign key(school_id,grade_item_id) references public.classroom_grade_items(school_id,id) on delete cascade,foreign key(school_id,student_id) references public.students(school_id,id) on delete cascade);
create table public.classroom_quizzes(id uuid primary key default gen_random_uuid(),school_id uuid not null references public.schools(id) on delete cascade,classroom_id uuid not null,title text not null,instructions text,due_at timestamptz,time_limit_minutes integer check(time_limit_minutes is null or time_limit_minutes between 1 and 180),attempts_allowed integer not null default 1 check(attempts_allowed between 1 and 10),status text not null default 'draft' check(status in('draft','published','closed')),created_by uuid not null references auth.users(id),published_at timestamptz,created_at timestamptz not null default now(),unique(school_id,id),foreign key(school_id,classroom_id) references public.learning_classrooms(school_id,id) on delete cascade);
create table public.classroom_quiz_questions(id uuid primary key default gen_random_uuid(),school_id uuid not null references public.schools(id) on delete cascade,quiz_id uuid not null,position integer not null,kind text not null check(kind in('single_choice','multiple_choice','true_false','short_text')),prompt text not null,options jsonb,correct_answer jsonb,marks numeric(7,2) not null check(marks>0),unique(quiz_id,position),unique(school_id,id),foreign key(school_id,quiz_id) references public.classroom_quizzes(school_id,id) on delete cascade);
create table public.classroom_quiz_attempts(id uuid primary key default gen_random_uuid(),school_id uuid not null references public.schools(id) on delete cascade,quiz_id uuid not null,student_id uuid not null,attempt_number integer not null,status text not null default 'in_progress' check(status in('in_progress','submitted','graded')),score numeric(7,2),maximum_score numeric(7,2),started_at timestamptz not null default now(),submitted_at timestamptz,unique(quiz_id,student_id,attempt_number),unique(school_id,id),foreign key(school_id,quiz_id) references public.classroom_quizzes(school_id,id) on delete cascade,foreign key(school_id,student_id) references public.students(school_id,id) on delete cascade);
create table public.classroom_quiz_answers(id uuid primary key default gen_random_uuid(),school_id uuid not null references public.schools(id) on delete cascade,attempt_id uuid not null,question_id uuid not null,answer jsonb not null,awarded_marks numeric(7,2),saved_at timestamptz not null default now(),unique(attempt_id,question_id),foreign key(school_id,attempt_id) references public.classroom_quiz_attempts(school_id,id) on delete cascade,foreign key(school_id,question_id) references public.classroom_quiz_questions(school_id,id) on delete cascade);
create table public.gradebook_formal_exports(id uuid primary key default gen_random_uuid(),school_id uuid not null references public.schools(id) on delete cascade,grade_item_id uuid not null,term_id uuid not null,assessment_id uuid not null,exported_by uuid not null references auth.users(id),exported_at timestamptz not null default now(),unique(grade_item_id,term_id),foreign key(school_id,grade_item_id) references public.classroom_grade_items(school_id,id),foreign key(school_id,term_id) references public.academic_terms(school_id,id),foreign key(school_id,assessment_id) references public.assessment_definitions(school_id,id));
do $$declare t text;begin foreach t in array array['classroom_grade_items','classroom_grades','classroom_quizzes','classroom_quiz_questions','classroom_quiz_attempts','classroom_quiz_answers','gradebook_formal_exports'] loop execute format('alter table public.%I enable row level security',t);execute format('create policy %I_read on public.%I for select to authenticated using(public.is_school_member(school_id))',t,t);end loop;end$$;
grant select on public.classroom_grade_items,public.classroom_grades,public.classroom_quizzes,public.classroom_quiz_questions,public.classroom_quiz_attempts,public.classroom_quiz_answers,public.gradebook_formal_exports to authenticated,service_role;grant insert,update,delete on public.classroom_grade_items,public.classroom_grades,public.classroom_quizzes,public.classroom_quiz_questions,public.classroom_quiz_attempts,public.classroom_quiz_answers,public.gradebook_formal_exports to service_role;

create or replace function public.export_grade_item_to_formal_results(_school uuid,_item uuid,_term uuid,_weight numeric,_actor uuid) returns public.assessment_definitions language plpgsql security definer set search_path='' as $$declare _itemrow public.classroom_grade_items;_room public.learning_classrooms;_assessment public.assessment_definitions;begin select * into _itemrow from public.classroom_grade_items where school_id=_school and id=_item and status='released';select * into _room from public.learning_classrooms where school_id=_school and id=_itemrow.classroom_id;if _itemrow.id is null or not public.can_manage_school(_school,_actor) then raise exception 'Released grade item and formal results permission required.' using errcode='42501';end if;if exists(select 1 from public.result_workflows where school_id=_school and term_id=_term and class_id=_room.class_id and status not in('draft','reopened')) then raise exception 'Formal result workflow is locked.' using errcode='23514';end if;insert into public.assessment_definitions(school_id,term_id,class_id,subject_id,name,maximum_score,weight_percent,created_by) values(_school,_term,_room.class_id,_room.subject_id,_itemrow.title,_itemrow.maximum_score,_weight,_actor) returning * into _assessment;insert into public.result_scores(school_id,assessment_id,student_id,score,remark,recorded_by) select _school,_assessment.id,g.student_id,g.score,g.feedback,_actor from public.classroom_grades g where g.school_id=_school and g.grade_item_id=_item and g.released_at is not null;insert into public.gradebook_formal_exports(school_id,grade_item_id,term_id,assessment_id,exported_by) values(_school,_item,_term,_assessment.id,_actor);insert into public.audit_events(school_id,actor_id,action,entity_type,entity_id,metadata) values(_school,_actor,'gradebook.exported.formal','assessment',_assessment.id,jsonb_build_object('gradeItemId',_item,'termId',_term));return _assessment;end$$;
revoke all on function public.export_grade_item_to_formal_results(uuid,uuid,uuid,numeric,uuid) from public,anon,authenticated;grant execute on function public.export_grade_item_to_formal_results(uuid,uuid,uuid,numeric,uuid) to service_role;
